import datetime
from typing import Optional
import jwt
from passlib.context import CryptContext

# Retrieve JWT secret; enforce a minimum length of 256 bits (32 bytes) for HS256.
_env_secret = os.getenv("JWT_SECRET_KEY")
if not _env_secret:
    raise RuntimeError("Environment variable JWT_SECRET_KEY must be set")
if len(_env_secret.encode()) < 32:
    raise RuntimeError("JWT_SECRET_KEY is too short; must be at least 32 bytes for HS256")
secret_key = _env_secret

# Use pbkdf2_sha256 which does not require external bcrypt
pwd_context = CryptContext(schemes=["pbkdf2_sha256"], deprecated="auto")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)

def get_password_hash(password: str) -> str:
    return pwd_context.hash(password)

def create_access_token(user_id: int, expires_delta: Optional[datetime.timedelta] = None) -> str:
    algorithm = "HS256"
    expire = datetime.datetime.utcnow() + (expires_delta or datetime.timedelta(days=30))
    to_encode = {"sub": str(user_id), "exp": expire}
    encoded_jwt = jwt.encode(to_encode, secret_key, algorithm=algorithm)
    return encoded_jwt

def decode_token(token: str) -> int:
    algorithm = "HS256"
    payload = jwt.decode(token, secret_key, algorithms=[algorithm])
    user_id: str = payload.get("sub")
    if user_id is None:
        raise jwt.InvalidTokenError("Missing sub claim")
    return int(user_id)
