{"path":"backend/app/auth.py","content":"import os
import datetime
from typing import Optional
import jwt
from passlib.context import CryptContext
import sys

# Ensure JWT secret is provided and has sufficient length
_secret = os.getenv("JWT_SECRET_KEY")
if not _secret or len(_secret.encode()) < 32:
    # In production, a strong secret must be provided
    raise RuntimeError("JWT_SECRET_KEY must be set to a secret of at least 32 bytes")
secret_key = _secret

# Use pbkdf2_sha256 which does not require external bcrypt
pwd_context = CryptContext(schemes=["pbkdf2_sha256"], deprecated="auto")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)

def get_password_hash(password: str) -> str:
    return pwd_context.hash(password)

def create_access_token(user_id: int, expires_delta: Optional[datetime.timedelta] = None) -> str:
    algorithm = "HS256"
    expire = datetime.datetime.utcnow() + (expires_delta or datetime.timedelta(days=30))
    to_encode = {"sub": str(user_id), "exp": expire}
    encoded_jwt = jwt.encode(to_encode, secret_key, algorithm=algorithm)
    return encoded_jwt

def decode_token(token: str) -> int:
    algorithm = "HS256"
    payload = jwt.decode(token, secret_key, algorithms=[algorithm])
    user_id: str = payload.get("sub")
    if user_id is None:
        raise jwt.InvalidTokenError("Missing sub claim")
    return int(user_id)
"}

{"path": "expo-app/src/auth.ts", "content": "import { Platform } from 'react-native';
// Native SecureStore for iOS/Android
import * as SecureStore from 'expo-secure-store';

const TOKEN_KEY = 'jwt_token';

// Helper functions for web cookie handling
function setCookie(name: string, value: string, days = 7) {
  const expires = new Date(Date.now() + days * 864e5).toUTCString();
  const sameSite = 'Strict';
  const secure = location.protocol === 'https:' ? '; Secure' : '';
  document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/; SameSite=${sameSite}${secure}`;
}

function getCookie(name: string) {
  const match = document.cookie.match(new RegExp('(?:^|; )' + name.replace(/([.$?*|{}()\[\]\\\/\+^])/g, '\\$1') + '=([^;]*)'));
  return match ? decodeURIComponent(match[1]) : null;
}

function deleteCookie(name: string) {
  document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/`;
}

export async function saveToken(token: string): Promise<void> {
  if (Platform.OS === 'web') {
    setCookie(TOKEN_KEY, token);
  } else {
    await SecureStore.setItemAsync(TOKEN_KEY, token);
  }
}

export async function getToken(): Promise<string | null> {
  if (Platform.OS === 'web') {
    return getCookie(TOKEN_KEY);
  }
  return await SecureStore.getItemAsync(TOKEN_KEY);
}

export async function deleteToken(): Promise<void> {
  if (Platform.OS === 'web') {
    deleteCookie(TOKEN_KEY);
  } else {
    await SecureStore.deleteItemAsync(TOKEN_KEY);
  }
}
"}

{"path": "expo-app/deleteVulnDeps.js", "content": "const fs = require('fs');
const path = require('path');
const lockPath = path.join(__dirname, 'package-lock.json');
let lock;
try {
  lock = JSON.parse(fs.readFileSync(lockPath, 'utf8'));
} catch (e) {
  console.error('Failed to read lockfile', e);
  process.exit(1);
}
// Packages to remove entirely
const removePkgs = ['node-forge'];
// For braces, ensure version >=4.0.0; remove if older
function isSafeBrace(version) {
  // simple check: major >=4
  const major = parseInt(version.split('.')[0] || '0', 10);
  return major >= 4;
}
if (lock.packages) {
  for (const pkg in lock.packages) {
    const info = lock.packages[pkg];
    const name = pkg.replace('node_modules/', '').split('/')[0];
    if (removePkgs.includes(name)) {
      delete lock.packages[pkg];
    } else if (name === 'braces') {
      const ver = info.version;
      if (!isSafeBrace(ver)) {
        delete lock.packages[pkg];
      }
    }
  }
}
fs.writeFileSync(lockPath, JSON.stringify(lock, null, 2));
console.log('Removed vulnerable deps from lockfile');
"}

